<?php require_once '../includes/auth.php'; require_role('admin'); $page_title='Users';
if(isset($_POST['add'])){ $name=clean($conn,$_POST['name']); $email=clean($conn,$_POST['email']); $role=clean($conn,$_POST['role']); $parent=(int)$_POST['parent_id']; $pass=password_hash($_POST['password'],PASSWORD_DEFAULT); mysqli_query($conn,"INSERT INTO users(name,email,password,role,parent_id,status) VALUES('$name','$email','$pass','$role',$parent,'active')"); log_audit($conn,$_SESSION['user_id'],'Create User',"$role $email"); redirect('users.php'); }
include '../includes/header.php'; include '../includes/sidebar.php'; $users=mysqli_query($conn,"SELECT u.*,p.name parent_name FROM users u LEFT JOIN users p ON p.id=u.parent_id ORDER BY u.id DESC"); $parents=mysqli_query($conn,"SELECT id,name,role FROM users WHERE role!='shop'"); ?>
<div class="row g-4"><div class="col-lg-4"><div class="card-box"><h5>Add User</h5><form method="POST"><input class="form-control mb-2" name="name" placeholder="Name" required><input class="form-control mb-2" name="email" type="email" placeholder="Email" required><input class="form-control mb-2" name="password" placeholder="Password" required><select class="form-select mb-2" name="role"><option>supplier</option><option>distributor</option><option>shop</option></select><select class="form-select mb-3" name="parent_id"><option value="1">Admin</option><?php while($p=mysqli_fetch_assoc($parents)){ ?><option value="<?php echo $p['id']; ?>"><?php echo $p['name'].' ('.$p['role'].')'; ?></option><?php } ?></select><button class="btn btn-success" name="add">Add User</button></form></div></div><div class="col-lg-8"><div class="card-box"><h5>All Users</h5><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Parent</th><th>Status</th></tr><?php while($u=mysqli_fetch_assoc($users)){ ?><tr><td><?php echo $u['name']; ?></td><td><?php echo $u['email']; ?></td><td><?php echo $u['role']; ?></td><td><?php echo $u['parent_name']; ?></td><td><span class="badge-soft"><?php echo $u['status']; ?></span></td></tr><?php } ?></table></div></div></div><?php include '../includes/footer.php'; ?>
